-- Generated by scripts/generate-seed.mjs — do not edit by hand.

-- collections (one per brand)
on conflict (id) do update set name = excluded.name, country = excluded.country, aliases = excluded.aliases;

-- cars
on conflict (id) do update set model = excluded.model, generation = excluded.generation, year_from = excluded.year_from, year_to = excluded.year_to, power = excluded.power, country = excluded.country, price_new = excluded.price_new, rarity = excluded.rarity, aliases = excluded.aliases;

-- badges (catalogue only — unlocks are derived from garage)
on conflict (id) do update set name = excluded.name, description = excluded.description, target = excluded.target;
